{"command": "cat > /app/solve.py << 'PYEOF'
import json
import glob
from collections import defaultdict

user_amounts = defaultdict(float)
user_items = defaultdict(int)
tag_counts = defaultdict(int)

for filepath in glob.glob("/app/records_*.jsonl"):
    with open(filepath) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            record = json.loads(line)
            user = record["user"]
            user_amounts[user] += record["amount"]
            user_items[user] += record["items"]
            for tag in record.get("tags", []):
                tag_counts[tag] += 1

# Top 5 users by amount
sorted_users = sorted(user_amounts.items(), key=lambda x: x[1], reverse=True)[:5]
top_5_users = {}
for user, amount in sorted_users:
    top_5_users[user] = {
        "total_amount": round(amount, 2),
        "total_items": user_items[user]
    }

# Top 5 tags by count
sorted_tags = sorted(tag_counts.items(), key=lambda x: x[1], reverse=True)[:5]
top_5_tags = {}
for tag, count in sorted_tags:
    top_5_tags[tag] = {"count": count}

result = {
    "top_5_users_by_amount": top_5_users,
    "top_5_tags_by_count": top_5_tags
}

with open("/app/aggregates.json", "w") as f:
    json.dump(result, f, indent=2)

print(json.dumps(result, indent=2))
PYEOF
python /app/solve.py"}
